const rawInput = $input.first().json;
const alerts = rawInput.body?.alerts || rawInput.alerts || [];
const firingAlerts = alerts.filter(a => a.status === 'firing');
if (firingAlerts.length === 0) {
  const directTarget = rawInput.body?.target || rawInput.target || rawInput.body?.container || rawInput.container;
  if (directTarget) return [{ json: { has_alert: true, alerts_count: 1, issues_detail: [{ target: directTarget, alert_name: 'ManualTestAlert', severity: 'warning', summary: 'Manual trigger test alert' }] } }];
  return []; 
}
const alert = firingAlerts[0];
const parsedIssue = {
  target: alert.labels?.container || alert.labels?.instance || alert.labels?.job || 'metabase',
  alert_name: alert.labels?.alertname || 'ContainerDown',
  severity: alert.labels?.severity || 'warning',
  summary: alert.annotations?.summary || alert.annotations?.description || 'Connection issue'
};
return [{ json: { has_alert: true, alerts_count: 1, issues_detail: [parsedIssue] } }];

const alertTarget = $('Parse Prometheus Alert').first().json.issues_detail?.[0]?.target || '';
const cleanTarget = alertTarget.split(':')[0].toLowerCase();
const req = typeof helpers !== 'undefined' ? helpers.httpRequest : $helpers.httpRequest;

const defaultPveToken = $env.get('PROXMOX_API_TOKEN') || '';
const defaultLocalIp = $env.get('N8N_LOCAL_IP') || '192.168.1.41';

// PROXMOX HOSTS LIST
const PVE_NODES = [
  { name: 'pve',  ip: defaultLocalIp, token: defaultPveToken }
];
const DOCKER_HOSTS = [
  { url: `http://${defaultLocalIp}:2375`, ip: defaultLocalIp, name: 'docker-core' }
];

const STATIC_MAPPINGS = {
  'metabase': { name: 'metabase', type: 'container', action: 'restart', node_ip: defaultLocalIp },
  'n8n': { name: 'n8n', type: 'container', action: 'restart', node_ip: defaultLocalIp },
  'adguard': { name: 'adguard', type: 'container', action: 'restart', node_ip: defaultLocalIp },
  'security-stack': { id: 300, name: 'security-stack', type: 'lxc', action: 'pct_start', node_ip: defaultLocalIp }
};

let matchedAsset = null;
let searchKey = cleanTarget;

for (const [key, map] of Object.entries(STATIC_MAPPINGS)) {
  if (alertTarget.includes(key) || cleanTarget.includes(key)) {
    if (map.type === 'qemu' || map.type === 'lxc') {
      matchedAsset = { found_in: 'proxmox', type: map.type, id: map.id, name: map.name, node_ip: map.node_ip, pve_token: PVE_NODES.find(n => n.ip === map.node_ip)?.token || '', recommended_action: map.action, status: 'unknown' };
      break;
    } else if (map.type === 'container') {
      matchedAsset = { found_in: 'docker', type: 'container', id: map.name, name: map.name, node_ip: map.node_ip, recommended_action: map.action, status: 'exited' };
      break;
    }
  }
}

if (!matchedAsset) {
  for (const config of PVE_NODES) {
    try {
      const pveRes = await req({ method: 'GET', url: `https://${config.ip}:8006/api2/json/cluster/resources`, headers: { 'Authorization': config.token }, skipSslCertificateValidation: true, rejectUnauthorized: false, timeout: 3000, json: true });
      for (const item of (pveRes.data || [])) {
        if (item.type !== 'qemu' && item.type !== 'lxc') continue;
        const name = (item.name || '').toLowerCase();
        if (searchKey.includes(String(item.vmid)) || name.includes(searchKey) || searchKey.includes(name)) {
          matchedAsset = { found_in: 'proxmox', type: item.type, id: item.vmid, name: item.name, node_name: item.node || config.name, node_ip: config.ip, pve_token: config.token, recommended_action: item.type === 'lxc' ? 'pct_start' : 'qm_start', status: item.status };
          break;
        }
      }
    } catch(e) {}
    if (matchedAsset) break;
  }
}

if (!matchedAsset) {
  for (const dockerHost of DOCKER_HOSTS) {
    try {
      const dockerRes = await req({ method: 'GET', url: `${dockerHost.url}/containers/json?all=1`, timeout: 3000, json: true });
      for (const c of dockerRes) {
        const names = (c.Names || []).map(n => n.replace('/', '').toLowerCase());
        if (names.some(n => searchKey.includes(n) || n.includes(searchKey))) {
          matchedAsset = { found_in: 'docker', type: 'container', id: names[0], name: names[0], node_ip: dockerHost.ip, recommended_action: 'restart', status: c.State };
          break;
        }
      }
    } catch(e) {}
    if (matchedAsset) break;
  }
}

if (!matchedAsset) {
  matchedAsset = { found_in: 'docker', type: 'container', id: searchKey, name: searchKey, node_ip: defaultLocalIp, recommended_action: 'restart', status: 'unknown' };
}

return [{ json: { target_raw: alertTarget, asset: matchedAsset } }];

const directMem = $input.first()?.json || {};
const assetData = $('Live Auto-Discovery Agent').first()?.json || {};
const asset = assetData.asset || {};
let memAction = directMem.action;

if (asset.type === 'container' && memAction && !['restart', 'start', 'stop'].includes(memAction)) {
  memAction = 'restart';
}
if (directMem && memAction) {
  return [{ json: {
    bypass_ai: true,
    action: memAction,
    target: asset.name || assetData.target_raw,
    asset_type: asset.type || 'container',
    vmid: asset.id || null,
    node_ip: asset.node_ip || $env.get('N8N_LOCAL_IP'),
    pve_token: asset.pve_token || '',
    risk: 'low',
    reason: "Recurring incident - 0-Token Recovery via TLab RAG Memory",
    command: `docker restart ${asset.name || asset.id}`,
    proposed_at: new Date().toISOString()
  } }];
}
return [{ json: { bypass_ai: false } }];

const openrouterData = $('Call Ling-3.0 AI').first().json;
const choice = openrouterData.choices?.[0];
if (choice?.finish_reason === 'length') return [{ json: { has_alert: false, summary: "⚠️ AI Token Overflow!" } }];
const rawText = choice?.message?.content || '{}';
let cleanText = rawText;
const firstBrace = rawText.indexOf('{');
const lastBrace = rawText.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1) cleanText = rawText.substring(firstBrace, lastBrace + 1);
let analysis;
try { analysis = JSON.parse(cleanText); } catch(e) { return [{ json: { has_alert: false, summary: "JSON Parse Error" } }]; }
let issues = analysis.issues || [];
if (!issues.length) return [{ json: { has_alert: false, summary: "Normal" } }];
const topIssue = issues[0];
const asset = $('Build Reasoning Prompt').first().json.asset;
let finalAction = topIssue.action || asset.recommended_action || 'restart';
if (asset.type === 'container' && !['restart', 'start', 'stop'].includes(finalAction)) finalAction = 'restart';
return [{ json: {
  has_alert: true,
  action: finalAction,
  target: asset.name || topIssue.target,
  asset_type: asset.type || 'container',
  vmid: asset.id || null,
  node_ip: asset.node_ip || $env.get('N8N_LOCAL_IP'),
  pve_token: topIssue.pve_token || asset.pve_token || '',
  risk: (topIssue.tier === 'auto') ? 'low' : 'high',
  reason: topIssue.reason || topIssue.root_cause || 'Service recovery for container',
  command: `docker restart ${asset.name}`,
  proposed_at: new Date().toISOString()
} }];
